/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_exo_unchecked`.
#[inline]
pub fn root_as_exo(buf: &[u8]) -> Result<EXO<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<EXO>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `EXO` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_exo_unchecked`.
#[inline]
pub fn size_prefixed_root_as_exo(buf: &[u8]) -> Result<EXO<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<EXO>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `EXO` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_exo_unchecked`.
#[inline]
pub fn root_as_exo_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<EXO<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<EXO<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `EXO` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_exo_unchecked`.
#[inline]
pub fn size_prefixed_root_as_exo_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<EXO<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<EXO<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a EXO and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `EXO`.
#[inline]
pub unsafe fn root_as_exo_unchecked(buf: &[u8]) -> EXO<'_> {
    unsafe { ::flatbuffers::root_unchecked::<EXO>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed EXO and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `EXO`.
#[inline]
pub unsafe fn size_prefixed_root_as_exo_unchecked(buf: &[u8]) -> EXO<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<EXO>(buf) }
}

pub const EXO_IDENTIFIER: &str = "$EXO";

#[inline]
pub fn exo_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, EXO_IDENTIFIER, false)
}

#[inline]
pub fn exo_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, EXO_IDENTIFIER, true)
}

#[inline]
pub fn finish_exo_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<EXO<'a>>
) {
    fbb.finish(root, Some(EXO_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_exo_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<EXO<'a>>
) {
    fbb.finish_size_prefixed(root, Some(EXO_IDENTIFIER));
}
